const D = { scale:1, density:.55, energy:.6, speed:1, mu:.15, hue:196, x:.5, y:.5, style:'bioluminescent', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const style = P.style;
// coarse Lenia grid (continuous CA); image()-upscaled
const GW = 108, GH = Math.max(48, Math.round(GW * height / width));
const N = GW * GH;
const R = Math.max(5, Math.min(18, Math.round(7 + P.scale * 6)));   // kernel radius (creature size)

function fr(i){ const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); }

// (re)allocate fields + buffer on size change
if (!S.g || S.gw !== GW || S.gh !== GH) {
  S.g = createGraphics(GW, GH); S.g.pixelDensity(1); S.gw = GW; S.gh = GH;
  S.A = new Float32Array(N); S.U = new Float32Array(N); S.seeded = false; S.Rused = -1;
}
// (re)build sparse ring kernel on radius change (Lenia shell kernel)
if (S.Rused !== R) {
  S.Rused = R;
  const kdx = [], kdy = [], kw = [];
  let sum = 0;
  for (let dy = -R; dy <= R; dy++) for (let dx = -R; dx <= R; dx++) {
    const rr = Math.sqrt(dx*dx + dy*dy) / R;
    if (rr < 1e-6 || rr >= 1) continue;
    const w = Math.exp(-((rr - 0.5)*(rr - 0.5)) / (2*0.15*0.15));  // single ring bump at r=0.5
    if (w < 0.02) continue;
    kdx.push(dx); kdy.push(dy); kw.push(w); sum += w;
  }
  for (let k = 0; k < kw.length; k++) kw[k] /= sum;
  S.kdx = Int16Array.from(kdx); S.kdy = Int16Array.from(kdy); S.kw = Float32Array.from(kw); S.kn = kw.length;
}

// smooth blob seeder
function seedBlob(cx, cy, rad, amp) {
  const Ar = S.A;
  for (let dy = -rad; dy <= rad; dy++) for (let dx = -rad; dx <= rad; dx++) {
    const d = Math.sqrt(dx*dx + dy*dy) / rad; if (d >= 1) continue;
    let gx = ((cx + dx) % GW + GW) % GW, gy = ((cy + dy) % GH + GH) % GH;
    const v = amp * (0.5 + 0.5*Math.cos(Math.PI*d)) * (0.6 + 0.4*fr(dx*7+dy*13+cx));
    const idx = gy*GW + gx; Ar[idx] = Math.min(1, Ar[idx] + v);
  }
}

// initial seeding (several blobs so creatures fill the frame)
if (!S.seeded || S.seedUsed !== P.seed) {
  S.seeded = true; S.seedUsed = P.seed;
  S.A.fill(0);
  const nb = 3 + Math.round(P.density * 7);
  for (let b = 0; b < nb; b++) {
    const cx = Math.floor(fr(b*3+1) * GW), cy = Math.floor(fr(b*3+2) * GH);
    seedBlob(cx, cy, R, 0.7 + fr(b*3+3)*0.3);
  }
  S.reseedAt = 0;
}

const Ar = S.A, Ur = S.U, kdx = S.kdx, kdy = S.kdy, kw = S.kw, kn = S.kn;
const mu = P.mu, sig = 0.025;
const dt = 0.11;
const steps = Math.max(1, Math.min(3, Math.round(P.speed * 1.4)));
const g2 = 2; // growth amplitude

// ---- Lenia update: A += dt * G( conv(A, ring) ) ----
for (let st = 0; st < steps; st++) {
  // convolution -> U (potential), with wrap-around
  for (let y = 0; y < GH; y++) {
    for (let x = 0; x < GW; x++) {
      let u = 0;
      for (let k = 0; k < kn; k++) {
        let sx = x + kdx[k]; if (sx < 0) sx += GW; else if (sx >= GW) sx -= GW;
        let sy = y + kdy[k]; if (sy < 0) sy += GH; else if (sy >= GH) sy -= GH;
        u += Ar[sy*GW + sx] * kw[k];
      }
      Ur[y*GW + x] = u;
    }
  }
  // growth
  const audioMu = mu + A.bass * 0.02;   // audio nudges morphology on top of baseline
  for (let i = 0; i < N; i++) {
    const u = Ur[i];
    const grow = g2 * Math.exp(-((u - audioMu)*(u - audioMu)) / (2*sig*sig)) - 1;
    let a = Ar[i] + dt * grow;
    Ar[i] = a < 0 ? 0 : (a > 1 ? 1 : a);
  }
}

// homeostasis: measure mass; reseed if the colony dies out or on section change (keeps it perpetually alive)
let mass = 0; for (let i = 0; i < N; i++) mass += Ar[i];
const massFrac = mass / N;
const sec = K.section | 0;
if (massFrac < 0.012 || (sec !== S.lastSec && K.t - S.reseedAt > 6)) {
  const cx = Math.floor(((fr(sec*5 + Math.floor(K.t*0.2)) )) * GW);
  const cy = Math.floor(((fr(sec*5 + 3 + Math.floor(K.t*0.2)))) * GH);
  seedBlob(cx, cy, R, 0.85);
  S.reseedAt = K.t;
}
S.lastSec = sec;

// ---- render A -> colour buffer ----
const gbuf = S.g; gbuf.loadPixels(); const px = gbuf.pixels;
const hb = ((P.hue + sec*17) % 360 + 360) % 360;
const expo = 0.7 + P.energy * 0.9 + A.rms * 0.5;
function pal(m){ const hr = hb/360; return [
  0.5 + 0.5*Math.cos(6.2831*(m + hr + 0.00)),
  0.5 + 0.5*Math.cos(6.2831*(m + hr + 0.33)),
  0.5 + 0.5*Math.cos(6.2831*(m + hr + 0.66)) ]; }
for (let i = 0; i < N; i++) {
  const a = Ar[i];
  const e = Math.min(1, a * expo);
  let r, gg, b;
  if (style === 'thermal') {
    r = Math.min(1, e*2.1); gg = Math.min(1, Math.max(0, e*2.0-0.5)); b = Math.min(1, Math.max(0, e*3.4-2.3));
  } else if (style === 'membrane') {          // green/violet cell-membrane
    const c = pal(0.35 + a*0.5); r = c[0]*e*0.9; gg = c[1]*e; b = c[2]*e*1.1;
  } else if (style === 'ink') {               // named mono — dark creatures on cream
    const s = 1 - Math.min(1, a*1.6); r = 0.92*s + 0.05; gg = 0.90*s + 0.05; b = 0.84*s + 0.05;
  } else if (style === 'plasma') {            // magenta/cyan
    const c = pal(a*0.8 + 0.15); r = Math.min(1,c[0]*e*1.15); gg = c[1]*e*0.8; b = Math.min(1,c[2]*e*1.15);
  } else {                                    // bioluminescent (default) — deep blue -> cyan -> yellow-white
    const t = Math.min(1, a*1.15);
    r = Math.min(1, Math.max(0, (t-0.55)*2.6) * expo + t*t*0.15);
    gg = Math.min(1, t*1.5*expo*0.7 + (t>0.6? (t-0.6)*1.8:0));
    b = Math.min(1, (0.15 + t*1.2) * expo * (style==='bioluminescent'?1:1));
  }
  // dim ground so frame-mean stays > floor even when sparse
  const p = i*4;
  px[p]   = Math.max(4, Math.min(255, r*255));
  px[p+1] = Math.max(6, Math.min(255, gg*255));
  px[p+2] = Math.max(10, Math.min(255, b*255));
  px[p+3] = 255;
}
gbuf.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(gbuf, 0, 0, width, height);
pop();
